"""Generate the agent API reference from its executable registry (no app import)."""

import json
from pathlib import Path

from ai_tools import TOOL_METADATA


def render_reference():
    lines = [
        '# AI Tool API Reference', '',
        'Generated by `python generate_ai_tool_docs.py`; do not edit by hand.', '',
        'These are internal agent tools, not arbitrary HTTP endpoints. The planner',
        'receives parameter schemas from this same registry. Execution checks the',
        'registered tool, required arguments, JSON types, enums and declared numeric',
        'bounds. Unknown arguments are rejected, not removed.', '',
        'Branch and user scope come from trusted request context, never model arguments.',
        'Delivery tools additionally enforce trusted manager/boss and active-branch scope.',
        'Delivery deletion requires a preview with a reason and a later explicit user',
        'confirmation tied to that exact record, identity and branch; model-supplied',
        'confirm=true is never approval, even in automatic mode. Other tools retain',
        'their existing execution policies. Access to the agent itself is manager/owner only',
        '(`/api/agent/*`); cashier accounts are denied. Failed tools are not evidence',
        'for a successful answer, and failed writes must never be blindly retried.', '',
        '## Delivery workflow limitations', '',
        '- Carrier updates are manual records, not live booking, calls or tracking sync.',
        '- Delivery details expose proof metadata/history/COD, never image or signature bytes.',
        '- Upload real photo/signature evidence through the secure delivery UI; the agent',
        '  must not invent evidence, fetch arbitrary URLs or claim it uploaded a proof.',
        '- Collection/remittance record actual COD ledger facts only; no bank transfer,',
        '  customer charge, refund or sale-accounting mutation is performed.',
        '- Active lists, detail and mutations exclude soft-deleted delivery profiles.', '',
        '## Sales query semantics', '',
        '- Best-selling products: `get_sales_trends(all_time=true)` for lifetime',
        '  gross unit rankings in the active branch, or `days` for a rolling period.',
        '- `all_time=true` overrides `days`; it never means a large guessed day count.',
        '- Trend revenue is gross line price × quantity, before returns and tax.',
        '- `total_products_sold` counts identifiable product groups, not units or transactions.',
        '- Missing/deleted product history is preserved in `unknown_product_sales`',
        '  (total_quantity, total_revenue, sale_count), never in product rankings.',
        '- Summary totals: `get_sales_summary`; `limit` limits recent rows only.',
        '- Results explicitly identify `period`, `period_days` and `branch_id`.', '',
    ]
    for name, meta in sorted(TOOL_METADATA.items()):
        lines.extend([
            f'## `{name}`', '', meta['description'], '',
            f"- Category: `{meta['category']}`",
            f"- Mutates data: `{meta['mutates']}`", '',
            *([f"- Trusted roles: `{', '.join(meta['requires_role'])}`",
               f"- Autonomy: `{meta['autonomy']}`",
               f"- Refresh sections: `{', '.join(meta['refresh_sections']) or 'none'}`", '']
              if 'requires_role' in meta else []),
            '### Arguments', '', '```json',
            json.dumps(meta['parameters'], indent=2, ensure_ascii=False), '```', '',
        ])
    return '\n'.join(lines)


if __name__ == '__main__':
    target = Path(__file__).resolve().parent / 'docs' / 'AI_TOOL_REFERENCE.md'
    target.write_text(render_reference(), encoding='utf-8')
    print(f'Generated {len(TOOL_METADATA)} tool contracts: {target}')